//! Ed25519 deploy keys generated by the panel.
//!
//! The private key is returned once to the caller, which encrypts it before
//! storage. It is not logged.

use ssh_key::{Algorithm, LineEnding, PrivateKey};

use crate::error::ApiError;

pub struct DeployKeyMaterial {
    pub public_key: String,
    pub private_openssh: String,
}

pub fn generate_deploy_key() -> Result<DeployKeyMaterial, ApiError> {
    let mut rng = rand_core06::OsRng;
    let key = PrivateKey::random(&mut rng, Algorithm::Ed25519).map_err(|_| {
        ApiError::new(
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            "keygen",
            "could not generate a deploy key",
        )
    })?;
    let public_key = key.public_key().to_openssh().map_err(|_| {
        ApiError::new(
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            "keygen",
            "could not encode the deploy key",
        )
    })?;
    let private_openssh = key.to_openssh(LineEnding::LF).map_err(|_| {
        ApiError::new(
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            "keygen",
            "could not encode the deploy key",
        )
    })?;
    Ok(DeployKeyMaterial {
        public_key,
        private_openssh: private_openssh.to_string(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deploy_key_is_openssh_ed25519() {
        let key = generate_deploy_key().unwrap();
        assert!(key.public_key.starts_with("ssh-ed25519 "));
        assert!(key.private_openssh.contains("BEGIN OPENSSH PRIVATE KEY"));
        assert!(!key.public_key.contains("BEGIN OPENSSH"));
    }
}
